x_comment(x_limitsObservationOfFrom,"(#$limitsObservationOfFrom STHG REG1 REG2) means that STHG conceals or in some manner limits the observation powers\npossible from REG2 when trying to observe REG1. This predicate\nembodies two aspects of the OCOKA principles, namely those of\nConcealment and of Observation. (#$limitsObservationOfFrom\nSmokeScreen001 GarnerValley GumbyHill) says that any object in\nGarnerValley has good concealment from observation from GumbyHill,\nsince SmokeScreen001 prevents observation of those objects from\nGumbyHill. So this predicate can be used to describe both Concealment\n(in this case, from the perspective of objects in GarnerValley -- cf. also #$providesConcealmentInCOA) and\nObservation (here, from the perspective of prospective observers on\nGumbyHill). Whether a unit seeks to maximize concealment or\nobservation is based on an interaction between the METT-TC principles.\nNote that if RedUnit001 occupied a position in GarnerValley and\nBlueUnit001 occupies GumbyHill, it is possible to use this predicate\nfor something like 'SmokeScreen001 currently limits the observation of\nRedUnit001 by BlueUnit001.'") :- x_cid(a65b12754960cd).
xc_microtheory(a65b12754960cd,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754960cd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754960cd,314).
xc_kb_names(a65b12754960cd,[]).
xc_mapping_rows(a65b12754960cd,[]).
x_comment(x_ExfiltrationFromEnemyTerritory,"To exfiltrate is to remove personnel or units from areas under enemy control by stealth, deception, surprise, or clandestine means. Exfiltration is conducted by friendly forces that have been encircled by enemy forces and cannot conduct a breakout or be relieved by other friendly forces. Forces returning from a raid, an infiltration, or a patrol behind enemy lines can also conduct an exfiltration. Exfiltration by an encircled force is used only as a last resort to preserve a portion of the force. It is preferable to the capture of the force. The exfiltrating force conducts it after destroying or incapacitating all equipment (less medical) not accompanying the force. The exfiltrating force may have to leave casualties in place with supplies, chaplain support, and medical attendants.") :- x_cid(a65b12754960ce).
xc_microtheory(a65b12754960ce,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754960ce,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754960ce,330).
xc_kb_names(a65b12754960ce,[]).
xc_mapping_rows(a65b12754960ce,[]).
x_comment(x_notEquipmentOfUnitType,"(notEquipmentOfUnitType ?UNITTYPE \n\n?THINGTYPE) means that under 'ordinary' or 'normal' circumstances we should\n\n not expect to find any instances of?UNITTYPE equipped with one or more\n\n instances of ?THINGTYPE.  Compare this to #$standardEquipmentOfUnitType,\n\n which basically states the opposite.") :- x_cid(a65b12754960cf).
xc_microtheory(a65b12754960cf,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754960cf,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754960cf,331).
xc_kb_names(a65b12754960cf,[]).
xc_mapping_rows(a65b12754960cf,[]).
x_comment(x_NoFireArea,"Areas with this attribute in a COA context are areas in\nwhich no fires or effects of fires are allowed. Two exceptions are (1)\nwhen establishing headquarters approves fires temporarily within the\nNFA on a mission basis, and (2) when the enemy force within the NFA\nengages a friendly force, the commander may engage the enemy to defend\nhis force.") :- x_cid(a65b12754960d0).
xc_microtheory(a65b12754960d0,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754960d0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
