x_comment('x_issuingOrder-Military',"'(#$issuingOrder-Military ORDERING PERSON) <MT TIME PAR>' means that PERSON is the author and issuing authority in ORDERING and is performing that issuing during TIME to granularity PAR in MT.  So this holds just during the time that the person is actively giving the order.") :- x_cid(a65b12754960d6).
