x_comment('x_Penetration-MilitaryManeuver',"This is the collection of instances of MilitaryManeuver-Offensive which are used when enemy flanks are not assailable. In a penetration, commanders mass sufficient combat power at the point of penetration to overwhelm the enemy and gain the advantage. FM 100-5.") :- x_cid(a65b12754960d8).
