x_comment(x_TerrainHighGround,"A military term and an instance of #$TerrainTypeBySurfaceLevel. The central feature point of high ground terrain (e.g. the hilltop of a hill) is typically higher in altitude than the surrounding terrain. This need not always be true, however, because a hill next to a larger hill would still be considered high ground. Instances of #$TerrainHighGround are #$Places that require one to traverse a positive slope in order to reach the central feature point. From a tactical standpoint, it is typically assumed that instances of #$TerrainHighGround enhance observation.") :- x_cid(a65b12754960d9).
xc_microtheory(a65b12754960d9,x_ModernMilitaryTacticsMt).
