xc_mapping_rows(a65b12754960d9,[]).
x_comment('x_Rupture-MilitaryTask',"To rupture is to create a gap in enemy defensive positions quickly. Rupture is directed against an enemy defensive force. Breach is the term used in conjunction with an obstacle.") :- x_cid(a65b12754960da).
