x_comment(x_militaryAlertStatus,"(#$militaryAlertStatus ORG LEVEL) means that the #$militaryAlertStatus of the #$MilitaryOrganization ORG is at LEVEL. Having a #$militaryAlertStatus at a certain level--#$highAmountOf, #$lowAmountOf, etc.--translates to a number of associated actions and behaviors depending on the organization type.  If (#$militaryAlertStatus ORG #$highAmountOf), for example, this might translate to a number of security and defense precautions being taken: increased patrols and security checks in the case of a deployed unit, for example.") :- x_cid(a65b12754960dd).
xc_microtheory(a65b12754960dd,x_ModernMilitaryTacticsMt).
