x_comment('x_ReliefInPlace-MilitaryTask',"A relief in place is an enabling operation in which ... all or part of a unit is replaced in an area by an incoming unit. ... Normally, the unit relieved is defending. However, a relief may set the stage for a resumption of offensive operations. A relief may also serve to free the relieved unit for other tasks, such as decontamination, reconstitution, routine rest, resupply, maintenance, or specialized training. Sometimes, as part of a larger operation, a commander wants the enemy to discover the relief because it will cause the enemy to do something in response that is prejudicial to his interest, such as move reserves from an area where the friendly commander wants to conduct a penetration. FM100-40, p18- 14,15.") :- x_cid(a65b12754960e1).
xc_microtheory(a65b12754960e1,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754960e1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
