x_comment(x_ViabilityForOperationFn,"(#$ViabilityForOperationFn OP_TYPE) returns a linearly ordered collection of instances of #$AttributeValue: in this case, regional viability levels that a particular region may have for a particular kind of military operation.  E.G., in order to say that Region01 is 'excellent for offensive operations' we would assert (#$terrainType Region01 (#$VeryHighAmountFn (#$ViabilityForOperationFn #$MilitaryOffensiveOperation))).") :- x_cid(a65b12754960e9).
