x_comment(x_unitHasPurpose,"(#$unitHasPurpose UNIT PROP) means that PROP is the purpose assigned to UNIT in the context of the Course of Action representation of which the assertion is a part.  This means that PROP is a proposition which UNIT is explicitly ordered to make true.") :- x_cid(a65b12754960eb).
xc_microtheory(a65b12754960eb,x_ModernMilitaryTacticsMt).
