x_comment('x_terrainAdvantage-SideDimensionDegree',"(#$terrainAdvantage-SideDimensionDegree LOC SIDE ADV-DIM ADV-AMT) means\nthat the location LOC has the potential to provide some #$TacticalAdvantage, where SIDE indicates whether the advantage is offensive or defensive, ADV-DIM indicates the tactical dimension of the advantage, and ADV-AMT indicates the degree of the advantage. For example, (#$terrainAdvantage-SideDimensionDegree Hill37 #$OffendingForce #$ConcealmentLimitingTerrain (#$MediumAmountFn #$TacticalAdvantage)) means that Hill37 has the potential to give the #$OffendingForce a medium level of #$TacticalAdvantage by limiting concealment. Note that #$TacticalAdvantages depend not just on terrain characteristics, but also on force and situation characteristics, and therefore belong to agents in fairly specific classes of real or potential military operations. For this reason, assertions stating the #$terrainAdvantage-SideDimensionDegree for some piece of terrain should be made only within appropriately scenario-specific contexts.") :- x_cid(a65b1275496101).
xc_microtheory(a65b1275496101,x_ModernMilitaryTacticsMt).
