x_comment(x_advanceGuardReserve,"(#$advanceGuardReserve SUPPORT UNIT) says that UNIT plays the role of reserve advance guard in the #$SupportingAUnit event SUPPORT.  Specifically, there is a larger unit of which UNIT is a part, the larger unit has been assigned a task, and UNIT has been sent out ahead of the larger unit to ensure its ability to advance and carry out its task.  During the instantiation of the task, UNIT gives direct support to the larger unit.") :- x_cid(a65b1275496103).
