x_comment(x_MilitaryControlMeasure,"Instances of #$SpatialThing-Localized which are accorded this attribute in a particular COA development scenario gain the status ofcoordination features which aid in that particular COA development process.  Instances are used in order to to assign responsibilities, coordinate fires and maneuver, and control combat operations. Each control measure can be portrayed graphically. In general, all control measures should be easily identifiable on the ground. Examples of control measures include boundaries, objectives, coordinating points, contact point, and direction of attack. From FM 101-5-1.") :- x_cid(a65b1275496107).
