x_comment('x_PassageOfLines-MilitaryOperation',"A passage of lines is an generally an operation in which one unit moves through another unit's positions with the intent of moving into or out of enemy contact. It involves the transfer of responsibility for fighting an enemy force from one unit to another in close operations.  The commander's reasons for conducting a passage of lines are to sustain the tempo of an offensive operation with fresh forces forces to a defense task. FM100-40, p18-2.") :- x_cid(a65b1275496116).
