x_comment(x_EngagementArea,"An area along an enemy avenue of approach where the commander intends to contain and destroy an enemy force with the massed fires of all available weapons. The size and shape of the engagement area is determined by the relatively unobstructed intervisibility from the weapon systems in their firing positions and the maximum range of those weapons. Sectors of fire are usually assigned to subordinates to prevent fratricide. See FMs 1-111, 1-112, 7-10, 7-20, 7-30, 17-95, 71-100, 71-123, 100-5, and 100-15.") :- x_cid(a65b127549611b).
