x_comment(x_ContainingAnEnemy,"Containing an enemy involves restricting his freedom of movement,e.g. by surrounding him.  In contexts involving a military force (see #$ModernMilitaryUnit-Deployable), containment of enemy forces can also involve causing them to center activity on a given front and prevent them from withdrawing any part of their forces for use elsewhere. The limits of the containment may be expressed in terms of geography or time. Containment allows an enemy to reposition himself within the designated geographic area, whereas fixing (see #$FixingAnEnemy) an enemy does not.") :- x_cid(a65b1275496121).
xc_microtheory(a65b1275496121,x_ModernMilitaryTacticsMt).
