x_comment(x_ForwardEdgeOfBattleArea,"The foremost limits of a series of areas in which ground combat units are deployed, excluding the areas in which the covering or screening forces are operating, designated to coordinate fire support, the positioning of (MBA). See FMs 1-111, 6-20 series, 7-20, 7-30, 71-100, 71-123, 100-5, and 100-15.") :- x_cid(a65b1275496125).
