x_comment(x_opTypeRequiresResourceType,"(#$opTypeRequiresResourceType OP_TYPE RES_TYPE) means that,\nin the context of the assertion, a #$MilitaryOperation OP of type\nOP_TYPE requires a #$PartiallyTangible of type RES_TYPE as a resource,\nin the sense that an instance INST of RES_TYPE in the context will be\n(#$resourceInEvent OP INST) in the context.") :- x_cid(a65b127549612b).
xc_microtheory(a65b127549612b,x_ModernMilitaryTacticsMt).
