x_comment(x_AxisOfAdvance,"A line of advance assigned for purposes of control; often a road or a group of roads, or a designated series of locations, extending in the direction of the enemy. (Army) - A general route of advance, assigned for purposes of control, which extends toward the enemy. An axis of advance symbol graphically portrays a commander's intention, such as avoidance of built-up areas or envelopment of an enemy force. It follows terrain suitable for the size of the force assigned the axis and is often a road, a group of roads, or a designated series of locations. A commander may maneuver his forces and supporting fires to either side of an axis of advance provided the unit remain oriented on the axis and the objective. Deviations from an assigned axis of advance must not interfere with the maneuver of adjacent units without prior approval of the higher commander. Enemy forces that do not threaten security or jeopardize mission accomplishment may be bypassed. An axis of advance is not used to direct the control of terrain or the clearance of enemy forces from specific locations. Intermediate objectives normally are assigned for these purposes.") :- x_cid(a65b1275496132).
xc_microtheory(a65b1275496132,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496132,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496132,615).
xc_kb_names(a65b1275496132,[]).
xc_mapping_rows(a65b1275496132,[]).
x_comment(x_FollowAndAssume,"Follow and assume is a task in which a committed force follows a force conducting an offensive operation. The committed force is prepared to continue the mission of the force it is following when that force is fixed, attrited, or unable to continue. The follow and assume force is not a reserve but is committed to accomplish specific tasks.") :- x_cid(a65b1275496133).
xc_microtheory(a65b1275496133,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496133,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496133,616).
xc_kb_names(a65b1275496133,[]).
xc_mapping_rows(a65b1275496133,[]).
x_comment(x_ControlPoint,"A position along a route of march at which men are stationed to give\n\ninformation and instructions for the regulation of supply or traffic..") :- x_cid(a65b1275496134).
xc_microtheory(a65b1275496134,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496134,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496134,617).
