xc_mapping_rows(a65b1275496134,[]).
x_comment('x_ReconnaissanceInForce-MilitaryOperation',"The collection of instances of MovementToContact in which a considerable military force locates the enemy and test its dispositions, strengths and reactions. Its purpose is to discover enemy weaknesses.") :- x_cid(a65b1275496135).
xc_microtheory(a65b1275496135,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496135,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496135,620).
xc_kb_names(a65b1275496135,[]).
xc_mapping_rows(a65b1275496135,[]).
x_comment('x_Security-MilitaryOperation',"The collection of all military operations conducted to protect the friendly force by providing early and accurate warning of enemy operations, to provide the force being protected with time and maneuver space within which to react to the enemy, and to develop the situation to allow the commander to effectively use the protected force. Security operations orient on the force or facility to be protected, rather than on the enemy. FM 100-40.") :- x_cid(a65b1275496136).
xc_microtheory(a65b1275496136,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496136,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496136,621).
xc_kb_names(a65b1275496136,[]).
xc_mapping_rows(a65b1275496136,[]).
x_comment(x_marchSpeedOfUnitTypeOnTerrain,"This predicate relates a military unit type to its typical march speed over unrestricted, restricted, or severely restricted terrain.  More precisely, (#$marchSpeedOfUnitTypeOnTerrain SPEED UNIT_TYPE TERRAIN_RESTRICTION) means that military vehicle of type UNIT_TYPE typically move at rate SPEED over terrain with movement restriction TERRAIN_RESTRICTION.  See also #$TerrainTypeByTrafficabilityLevel.") :- x_cid(a65b1275496137).
xc_microtheory(a65b1275496137,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496137,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496137,622).
xc_kb_names(a65b1275496137,[]).
xc_mapping_rows(a65b1275496137,[]).
x_comment(x_OccupyingAnObjective,"To occupy is to move onto an objective, key terrain, or other man-made or natural terrain area without opposition and to control that entire area. (See #$ControllingAnObjective.) Occupation of territory normally requires that the territory be under the authority and effective control of an armed force. To control the territory, the armed force conducts area security operations supported by information operations. This is not applicable to territory being administered in accordance with peace terms, treaty, or other agreement, express or implied, with civil authority of the territory.") :- x_cid(a65b1275496138).
xc_microtheory(a65b1275496138,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496138,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496138,623).
xc_kb_names(a65b1275496138,[]).
xc_mapping_rows(a65b1275496138,[]).
x_comment(x_MainAttackSpecification,"A specialization of #$Reporting in which the main attack of some COA is described.") :- x_cid(a65b1275496139).
xc_microtheory(a65b1275496139,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496139,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496139,624).
xc_kb_names(a65b1275496139,[]).
xc_mapping_rows(a65b1275496139,[]).
x_comment('x_Red-Side',"Placeholder term employed in the military decision-making process to designate generalized affiliation of 'hostile' or opposed units.") :- x_cid(a65b127549613a).
xc_microtheory(a65b127549613a,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549613a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549613a,625).
xc_kb_names(a65b127549613a,[]).
xc_mapping_rows(a65b127549613a,[]).
x_comment(x_vehicleConeIndex,"(vehicleConeIndex VEHICLE NR-OF-PASS VCI-VALUE) indicates the VCI  value for both the type of vehicle and their number of passes over the same  path .  The VCI value is necessary for determining whether a vehicle is able  to traverse a soil, especially if the soil is wet or damp.  For a particular  soil type, compare the #$ratingConeIndex to the vehicle's #$vehicleConeIndex. The military usually calculates with one pass, VCI-1, and fifty passes,  VCI-50.  For example, one #$M1A1AbramsTank (VCI-1 = 25) can traverse wet  clay (RCI=40).  However, 50 #$M1A1AbramsTank (VCI-50 = 58) will not be able  to traverse the same wet clay.") :- x_cid(a65b127549613b).
xc_microtheory(a65b127549613b,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549613b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549613b,626).
xc_kb_names(a65b127549613b,[]).
xc_mapping_rows(a65b127549613b,[]).
x_comment(x_SecuringAnObjective,"To secure is to gain possession of a position or terrain feature with or without force and try to prevent its destruction or loss by enemy action. A unit does not have to physically occupy a geographical location to secure it if the unit can prevent the enemy from occupying or firing at that location by other means. The subordinate tasks associated with secure are to prevent enemy direct and observed indirect fire from impacting on the secured area and to prevent any enemy forces from occupying or using the secured area.") :- x_cid(a65b127549613c).
xc_microtheory(a65b127549613c,x_ModernMilitaryTacticsMt).
