x_comment(x_forwardCommandPostOfUnit,"(#$forwardCommandPostOfUnit POST UNIT)  means that POST has           the status of being the forward #$CommandPost of UNIT in the           context in which the assertion is made.") :- x_cid(a65b127549613e).
