x_comment(x_AttackingByFire,"To attack by fire is to engage offensively the enemy with direct and indirect fire: to fix, destroy, suppress, or deceive him. The friendly force does not close with the enemy or occupy the objective. An attack by fire is usually a supporting effort during offensive operations and a counterattack by fire option for the reserve during defensive  operations. It is not done in conjunction with another maneuvering force. The force conducting an attack by fire may be assigned a battle position with either a sector of fire or an engagement area, or it may be assigned an axis of advance and a force-oriented objective.  The enemy may be stationary or moving. An attack by fire closely resembles the task of support by fire. The chief difference is that support by fire is conducted to support another force so that force can maneuver against the enemy.") :- x_cid(a65b1275496140).
xc_microtheory(a65b1275496140,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496140,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496140,637).
xc_kb_names(a65b1275496140,[]).
xc_mapping_rows(a65b1275496140,[]).
x_comment(x_areaToProtect,"(areaToProtect ?ENTITY) means that ?ENTITY is being protected. This\npredicate is used in the context of goals and causes. ") :- x_cid(a65b1275496141).
xc_microtheory(a65b1275496141,x_ModernMilitaryTacticsMt).
