x_comment('x_Envelopment-MilitaryManeuver',"In an envelopment, the main attack focuses on seizing an objective in the enemy rear that cuts his escape routes and subjects him to destruction in his current positions. In an envelopment operation, the commander seeks to strike an assailable flank. It avoids the enemy's strength - his front - where the effects of his fires and obstacles are the greatest. FM100-40, p3-18. ") :- x_cid(a65b1275496142).
