x_comment(x_BreachingAnEnemyDefense,"A Breach is both a tactical task and an enabling operation in which any means available are employed to break through or secure a passage through an enemy defense, obstacle, minefield, or fortification.  To maintain his tempo and momentum, a commander attempts to bypass and avoid obstacles to the maximum extent possible. Breaching enemy obstacle systems is normally his last choice. When they occur, they are a synchronized combined arms operation under the control of the maneuver commander. There are three types of breaching operations: hasty, deliberate, or assault. The type of breach conducted depends on the nature of the obstacle and the capabilities of the enemy force covering the obstacle.") :- x_cid(a65b127549614d).
xc_microtheory(a65b127549614d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549614d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549614d,663).
xc_kb_names(a65b127549614d,[]).
xc_mapping_rows(a65b127549614d,[]).
x_comment(x_moveCrossesPath,"(#$moveCrossesPath MOVE PATH) is true iff MOVE is an instance of\nMovement-TranslationEvent that goes across PATH. For this to be the case,\nthe following conditions must be satisfied: first, MOVE traverses a point\nthat is on PATH; second, MOVE's traversal begins at point START, ends at\npoint END, and START and END are located in distinct regions both of which\nhave PATH as common boundary.") :- x_cid(a65b127549614e).
xc_microtheory(a65b127549614e,x_ModernMilitaryTacticsMt).
