x_comment(x_ForwardLineOfOwnTroops,"A line which indicates the most forward positions of friendly forces in any kind of military operation at a specific time. The FLOT normally identifies the forward location of covering and screening forces. (Army) - The FLOT may be at, beyond, or short of the FEBA. An enemy FLOT indicates the forward most position of hostile forces. (See also #$LineOfContact (LC).)  See FMs 1-111, 6-20 series, 7-20, 7-30, 71-100, 71-123, 100-5, and 100-15.") :- x_cid(a65b1275496153).
xc_microtheory(a65b1275496153,x_ModernMilitaryTacticsMt).
