x_comment(x_TargetReferencePoint,"An easily recognizable point on the ground (either natural or man-made) used to initiate, distribute, and control fires. TRPs are designated by maneuver leaders from platoon through battalion to define battalion, company, platoon, section, squad, or individual sectors of fire and observation usually within an engagement area. TRPs can also designate the center of an area where the commander plans to distribute or converge the fires of all his weapons rapidly. TRPs are designated using the standard target symbol and numbers issued by maneuver commanders. Once approved by the battalion fire support officer, TRPs can be designated as indirect fire targets using the standard target symbol with letters and numbers issued by the fire support officer. (See also #$EngagementArea). See FMs 6-series, 7-7, 7-8, 7-10, 7-20, 7-90, 7-91, 17-12, 17-15, 17-9 and 23-1.") :- x_cid(a65b1275496155).
xc_microtheory(a65b1275496155,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496155,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496155,678).
