x_comment(x_mainAttackOfOperation,"This predicate relates an instance of #$MilitaryOperation to an instance of #AssignedTaskType which is a specialization of #$AttackOnTangible.  (#$mainAttackOfOperation OP ATTACK) means that ATTACK is considered to be the main attack of the #$MilitaryOperation OP within the plan specification context in which the assertion is made.  This entails (#$subTasks-Military OP TASK).") :- x_cid(a65b1275496169).
