x_comment('x_FrontalAttack-MilitaryManeuver',"The frontal attack is a military operation employed either to overrun or destroy a weaker enemy force or as a supporting or secondary force in conjunction with other choices of maneuver. ... It is also used by a friendly force that has overwhelming combat power to maintain momentum. ... Whereas the penetration is designed as a sharp attack to rupture the enemy position, the frontal attack is designed to maintain continuous pressure along the entire front until either a breach occurs or forces succeed in pushing the enemy back. FM100-40, p3-16.") :- x_cid(a65b127549616e).
xc_microtheory(a65b127549616e,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549616e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549616e,740).
xc_kb_names(a65b127549616e,[]).
xc_mapping_rows(a65b127549616e,[]).
x_comment(x_obstacleBlocks,"(#$obstacleBlocks AGT OBS) means that the obstacle OBS\nblocks AGT in some manner, and that AGT is not able to overcome OBS by\ncircumventing OBS. For instance, if (obstacleBlocks TankCompany001\nAlpMountainRange) is true, then TankCompany001 is not able to pass\nthrough AlpsMountainRange and also it is not possible to go around in\nan effective manner.") :- x_cid(a65b127549616f).
xc_microtheory(a65b127549616f,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549616f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549616f,741).
