xc_mapping_rows(a65b127549616f,[]).
x_comment(x_tacticalCombatForceInMission,"(#$tacticalCombatForceInMission MISSION  UNIT) means that UNIT \n\nplays the role of tactical combat force during MISSION.") :- x_cid(a65b1275496170).
xc_microtheory(a65b1275496170,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496170,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
