x_comment('x_AttackingByFire-Direct',"Instances of this collection are instances of #$AttackingByFire carried out using instances of #$DirectFireWeapon --i.e., projectile weapons such as guns which are aimed directly at the target.") :- x_cid(a65b1275496171).
xc_microtheory(a65b1275496171,x_ModernMilitaryTacticsMt).
