x_comment('x_termAssociatedWithMETT-TCPrinciple',"(termAssociatedWithMETT-TCPrinciple TERM PRIN) says that (object-level) knowledge about TERM is knowledge that falls under the METT-TC category, PRIN.  Assertions in which TERM is used should thus be displayed to the user as falling under PRIN.") :- x_cid(a65b1275496178).
xc_microtheory(a65b1275496178,x_ModernMilitaryTacticsMt).
