x_comment('x_AvenueOfApproach-Water',"A specialization of #$AvenueOfApproach for water-transported forces.  An\n#$AvenueOfApproach-Water is a route through one or more #$BodyOfWater that leads a force to its\nobjective, or to key terrain on its path.") :- x_cid(a65b1275496179).
xc_microtheory(a65b1275496179,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496179,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
