x_comment(x_mainCommandPostOfUnit,"(#$mainCommandPostOfUnit POST UNIT) means that POST has the status of being the main #$CommandPost of UNIT in the context in which the assertion is made.  This does NOT mean that UNIT is necessarily a headquarters unit, rather the SUBUNIT such that (#$headQuartersOfUnit UNIT SUBUNIT) operates out of POST as its main command center.") :- x_cid(a65b127549617a).
xc_microtheory(a65b127549617a,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
