xc_mapping_rows(a65b127549617a,[]).
x_comment(x_ArtilleryFire,"An important specialization of #$AttackingByFire, all instances of which are performed by some instance #$ArtilleryUnit-MilitarySpecialty.") :- x_cid(a65b127549617b).
xc_microtheory(a65b127549617b,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
