xc_mapping_rows(a65b127549617b,[]).
x_comment('x_MilitaryOperation-Joint',"A subset of #$MilitaryOperation, in which elements are planned military operations carried out by 2 or more parties working together.  These parties are often different branches of a country's military, or the militaries of several countries.  Examples include TheAlliedInvasionOfNormandy.") :- x_cid(a65b127549617c).
xc_microtheory(a65b127549617c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549617c,799).
xc_kb_names(a65b127549617c,[]).
xc_mapping_rows(a65b127549617c,[]).
x_comment('x_terrainAdvantage-SideDegree',"(#$terrainAdvantage-SideDegree LOC SIDE ADV-AMT) means\nthat the location LOC has the tactical potential to provide the degree of \n#$TacticalAdvantage ADV-AMT to SIDE. For example, (#$terrainAdvantage-SideDegree Hill28 #$OffendingForce (#$HighAmountFn #$TacticalAdvantage))\nmeans that Hill28 has the potential to offer the #$OffendingForce a\nhigh degree of #$TacticalAdvantage. Note that #$TacticalAdvantages\ndepend not just on terrain characteristics, but also on force and\nsituation characteristics, and therefore belong to agents in fairly\nspecific classes of real or potential military operations. For this\nreason, assertions stating the #$terrainAdvantage-SideDegree for some\npiece of terrain should be made only within appropriately\nscenario-specific contexts.") :- x_cid(a65b127549617d).
xc_microtheory(a65b127549617d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549617d,800).
xc_kb_names(a65b127549617d,[]).
xc_mapping_rows(a65b127549617d,[]).
x_comment(x_TroopMovement,"The collection of #$Translation-LocationChange    events in which military troops move or are transported from one place to another by any available means. Troop movements are either administrative or tactical (see FM100-40, p.17-1).") :- x_cid(a65b127549617e).
xc_microtheory(a65b127549617e,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549617e,811).
xc_kb_names(a65b127549617e,[]).
xc_mapping_rows(a65b127549617e,[]).
x_comment(x_FeintingAttack,"A #$FeintingAttack attemps to draw an enemy's attention and resources away from some main attack by promoting a misapprehension about the degree of threat posed by the feint. In a military conflict, this could be acheived by inducing an enemy to position his forces, commit his reserves or shift his fire support in reaction to the feint in ways which allow the main attack to be more effective.") :- x_cid(a65b127549617f).
xc_microtheory(a65b127549617f,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549617f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549617f,812).
xc_kb_names(a65b127549617f,[]).
xc_mapping_rows(a65b127549617f,[]).
x_comment('x_obstacleToFrom-Path',"(#$obstacleToFrom-Path OBS AGT PATH) means that OBS is an\nobstacle on the path PATH and provides AGT with some difficulty. OBS\neither blocks AGT from PATH completely, impedes AGT while AGT passes\nthrough it, or diverts AGT to some other path.") :- x_cid(a65b1275496180).
xc_microtheory(a65b1275496180,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496180,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496180,813).
xc_kb_names(a65b1275496180,[]).
xc_mapping_rows(a65b1275496180,[]).
x_comment(x_ExercisingCommandAndControl,"A collection of complex #$Events in which a commander in the Military Service exercises his authority over           subordinates that are assigned to a mission in order to carry out the mission.  The #$subEvents of any           instance of #$ExercisingCommandAndControl will most likely include making use of any available resources required for the mission (e.g. personnel and equipment) and then planning, organizing, directing, coordinating,           or controlling these resources, as well as any units assigned to the mission, in such a way that the           mission is successfully carried out.  Note that most of this comment is a near paraphrase of the definitions           of 'command' (JP 1-02) and 'command and control' (C2) (JP 1-02) from chapter 1 of the Army field           manual FM 101-5-1.  See http://www-cgsc.army.mil/cdd/F545/F545.htm.") :- x_cid(a65b1275496181).
xc_microtheory(a65b1275496181,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496181,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496181,817).
xc_kb_names(a65b1275496181,[]).
xc_mapping_rows(a65b1275496181,[]).
x_comment(x_ReinforcingAMilitaryForce,"A specialization of both #$MilitaryEvent and #$HelpingAnAgent.  Each instance of #$ReinforcingAMilitaryForce is an event in which some military force reinforces another military force.  The two military forces may be part of the same military organization, or they may come from cooperative, autonomous military organizations.") :- x_cid(a65b1275496182).
xc_microtheory(a65b1275496182,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496182,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496182,818).
xc_kb_names(a65b1275496182,[]).
xc_mapping_rows(a65b1275496182,[]).
x_comment(x_ObservationPost,"An instance of #$ObservationPost is a physical and \n\nengineered location that is intended to serve the purposes of a military unit, providing that \n\nunit with the ability to observe activities within an area of interest.") :- x_cid(a65b1275496183).
xc_microtheory(a65b1275496183,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496183,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
