x_comment('x_MilitarySupplyPoint-ClassI',"The collection of instances of #$MilitarySupplyPoint at which subsistence items such as ready-to-eat meals, T-rations, fresh fruits and vegetables, and health and comfort items are located and issued. FM 101-5-1.") :- x_cid(a65b1275496184).
