x_comment(x_LineOfContact,"A general trace delineating the location where two opposing forces are engaged.  (See also #$ForwardEdgeOfBattleArea (FEBA), #$ForwardLineOfOwnTroops (FLOT) and #$LineOfDeparture (LD).) See FMs 1-112, 7-7, 7-8, 7-10, 7-20, 7-30, 17-15, 17-95, and 71-123.") :- x_cid(a65b1275496185).
xc_microtheory(a65b1275496185,x_ModernMilitaryTacticsMt).
