xc_mapping_rows(a65b1275496185,[]).
x_comment(x_DefensivelyAdvantageousTerrain,"The collection of geographical regions that are useful for defensive actions. Note that it is possible for a geographical region to be both offensive and defensive. See #$OffensivelyAdvantageousTerrain.") :- x_cid(a65b1275496186).
xc_microtheory(a65b1275496186,x_ModernMilitaryTacticsMt).
