x_comment(x_ProbableLineOfDeployment,"A line selected on the ground, usually in the region of the\nlast covered and concealed position prior to the objective and forward\nof the line of departure, where attacking units deploy prior to\nbeginning an assault; it is generally used under conditions of limited\nvisibility.  From FM101-5-1.") :- x_cid(a65b1275496187).
xc_microtheory(a65b1275496187,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496187,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496187,827).
xc_kb_names(a65b1275496187,[]).
xc_mapping_rows(a65b1275496187,[]).
x_comment(x_DefendingForce,"A collection of individual military units. Each instance of\n#$DefendingForce is a military force in an defensive role in some real\nor potential military operations. Note that the same unit may be an\n#$DefendingForce in some situations and a #$OffendingForce in\nothers. For this reason, assertions making a specific unit an instance\nof #$DefendingForce should be made only within appropriately\nscenario-specific contexts. For the related collection of military\nunits that are specially optimized to conduct defensive operations,\nsee #$DefensiveOperationsUnit-MilitarySpecialty") :- x_cid(a65b1275496188).
xc_microtheory(a65b1275496188,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496188,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
