xc_mapping_rows(a65b1275496188,[]).
x_comment(x_COAMissionEssentialsMicrotheory,"A collection of microtheories.  The information in each\ninstance will inherit to some instance of\n#$COASpecificationMicrotheory, and in some cases, to multiple\ninstances.  Each instance of #$COAMissionEssentialsMicrotheory is used\nto specify the 'mission essential features' of the COAs that appear\namong the #$genlMt dependents, as a specified by the commander during\nthe mission analysis process.") :- x_cid(a65b1275496189).
xc_microtheory(a65b1275496189,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496189,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
