x_comment('x_ForwardPassageOfLines-MilitaryOperation',"A forward passage of lines occurs when a unit passes through a unit's positions while moving toward the enemy. FM100-40, p18-2. The purpose of a forward passage of lines is to conduct operations, such as an attack, reconnaissance, or security. This operation is designed to ensure maintenance of enemy contact. FM100-40, p18-8.") :- x_cid(a65b127549618a).
xc_microtheory(a65b127549618a,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549618a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
