xc_mapping_rows(a65b127549618a,[]).
x_comment('x_Retirement-MilitaryOperation',"A retirement is a task in a retrograde operation in which a force out of contact with the enemy moves away from the enemy, usually to the rear. A retiring unit organizes for combat but does not anticipate interference by enemy ground forces. FM100-40, p13-29.") :- x_cid(a65b127549618b).
xc_microtheory(a65b127549618b,x_ModernMilitaryTacticsMt).
