xc_mapping_rows(a65b127549618b,[]).
x_comment(x_delayUntilTime,"(delayUntilTime OP TEMP UNIT) means that in the instance of #$MilitaryOperation, OP, UNIT has been tasked with delaying enemy movement until the time interval started by TEMP.") :- x_cid(a65b127549618c).
xc_microtheory(a65b127549618c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549618c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
