x_comment(x_Interdiction,"To interdict is to prevent, hinder, or delay the enemy's use of an area or route. Interdiction is conducted to complement and reinforce other ongoing offensive or defensive operations. An interdiction tasking must specify the enemy force to be interdicted. It must also specify the area or route to be interdicted, how long the interdiction is to be in effect, defined either as a length of time or some event that must occur before the interdiction is lifted or the exact effect desired from the interdiction.") :- x_cid(a65b1275496191).
xc_microtheory(a65b1275496191,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496191,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496191,860).
xc_kb_names(a65b1275496191,[]).
xc_mapping_rows(a65b1275496191,[]).
x_comment(x_Airhead,"1. A designated area in a hostile or threatened territory which, when seized and held, ensures the continuous air landing of troops and material and provides maneuver space necessary for projected operations. Normally it is the area seized in the assault phase of an airborne operation. 2. A designated location in an area of operations used as a base for supply and evacuation by air.  (Army) - The airhead contains enough #$DropZones (DZs), #$LandingZones (LZs), and extraction zones (EZs) to ensure mass, interior lines of communication, and defense in depth. See FMs 71-100-2, 90-4, and JP 3-18.1.") :- x_cid(a65b1275496192).
xc_microtheory(a65b1275496192,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496192,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496192,861).
xc_kb_names(a65b1275496192,[]).
xc_mapping_rows(a65b1275496192,[]).
x_comment(x_complexityOfSituationTypeforPurpose,"(#$complexityOfSituationTypeforPurpose PLAN COMPLEXITY) holds just in case PLAN has the stated evaluatory COMPLEXITY.  For instance,  if (#$complexityOfSituationTypeforPurpose PLAN #$TooSimple) holds then attempts at carrying out the series of events depicted by PLAN  will likely be unsuccessful.") :- x_cid(a65b1275496193).
xc_microtheory(a65b1275496193,x_ModernMilitaryTacticsMt).
