xc_mapping_rows(a65b1275496193,[]).
x_comment(x_MissionSpecification,"A specialization of #$Reporting in which the mission for some COA is described.") :- x_cid(a65b1275496194).
xc_microtheory(a65b1275496194,x_ModernMilitaryTacticsMt).
