x_comment('x_ApproachMarch-MilitaryOperation',"#$ApproachMarch-MilitaryOperation is the collection of instances of #$MilitaryOperation that are conducted in order to close the distance between the unit(s) in question and the enemy, whose location is relatively certain. FM 100-5.") :- x_cid(a65b1275496195).
xc_microtheory(a65b1275496195,x_ModernMilitaryTacticsMt).
