x_comment(x_CounterattackByFire,"A specialization of #$Counterattack-MilitaryOperation.  Each instance is a #$MilitaryOperation and an offensive response to a #$MilitaryAttack, and is carried out by means of direct or indirect fires.") :- x_cid(a65b1275496196).
xc_microtheory(a65b1275496196,x_ModernMilitaryTacticsMt).
