x_comment('x_Retain-MilitaryTask',"To retain is to occupy and hold a terrain 18 feature so that the enemy can not occupy or use it. The commander assigning this task must specify the area to be retained and the duration of the retention, which is time- or event-driven. While a unit is conducting this task, decisive engagement can occur.") :- x_cid(a65b1275496197).
xc_microtheory(a65b1275496197,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496197,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496197,866).
