xc_mapping_rows(a65b1275496197,[]).
x_comment(x_SupportingByFire,"An instance of #$SupportingByFire closely resembles the task of #$AttackingByFire, but a fire support action need not be an attack at all (i.e., #$AttackOnTangible). Support by fire is artillery fire conducted to support another force so that force can maneuver against the enemy.") :- x_cid(a65b1275496198).
xc_microtheory(a65b1275496198,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496198,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
