xc_mapping_rows(a65b1275496198,[]).
x_comment(x_TacticalTerrainObject,"A collection of #$GeographicalThings.  Each instance of\n#$TacticalTerrainObject is a geographically located object, specified\nand given tactical status in the context of some real or hypothetical\nmilitary operations. #$TacticalTerrainObjects are generally named as\npart of the process of military planning.  They may or may not\ncorrespond to recognizable features of the underlying terrain.") :- x_cid(a65b1275496199).
xc_microtheory(a65b1275496199,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496199,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496199,868).
xc_kb_names(a65b1275496199,[]).
xc_mapping_rows(a65b1275496199,[]).
x_comment(x_attritionConstraintOfAction,"(#$attritionConstraintOfAction ACT QUANT) means that an\nexpected attrition level in excess of QUANT is not considered acceptable for\nthe military action ACT>.  The attrition constraint is generally given as a percentage or decimal fraction of the whole.") :- x_cid(a65b127549619a).
xc_microtheory(a65b127549619a,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
