xc_mapping_rows(a65b127549619a,[]).
x_comment('x_PassageOfLines-Forward',"Forward passage of lines occurs when a unit passes through another (friendly) unit's positions while moving toward the enemy.") :- x_cid(a65b127549619b).
xc_microtheory(a65b127549619b,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
