xc_mapping_rows(a65b127549619b,[]).
x_comment(x_coaSubTasks,"(#$coaSubTasks TASK SUBTASK) means that SUBTASK is considered a proper #$subEventTypes of TASK and presupposes that any unit assigned to perform SUBTASK is a #$subOrganizations of the unit assigned to perform TASK.  This relation is used to express the relationship between a task assigned to a particular military unit at one level of planning in the MDMP and the task assigned to a subunit of that unit at a lower level of planning.--Rode, Nov. 4, 1998") :- x_cid(a65b127549619c).
xc_microtheory(a65b127549619c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549619c,878).
xc_kb_names(a65b127549619c,[]).
xc_mapping_rows(a65b127549619c,[]).
x_comment(x_coaSynchronicity,"(#$coaSynchronicity COA ATTR) evaluates as ATTR, some\n#$SynchronicityOfComplexAction, the synchronicity of the attack plan outlined\nin COA.  The phases of a #$Synchronous attack are timed to complement\neach other.  For example, an attack just prior to a COA's main attack,\nand in a different location, can mislead the enemy about the main\nthrust of the attack, and fix a part of its force away from the\ndecision point.  #$An Asynchronous attack might be targeting enemy forces with artillery while\nalso attacking with helicopters, as this jeopardizes the friendly helicopters.") :- x_cid(a65b127549619d).
xc_microtheory(a65b127549619d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549619d,879).
xc_kb_names(a65b127549619d,[]).
xc_mapping_rows(a65b127549619d,[]).
x_comment('x_issuerOfOrder-Military',"(#$issuerOfOrder-Military ORDERING PERSON) means that PERSON is the author and issuing authority in ORDERING.  In such a case, it is assumed that ORDERING will have as an #$outputsCreated an instance of #$MilitaryOrder-IBO of which the #$issuerOfOrder-Military will be the #$informationArtifactAuthor.") :- x_cid(a65b127549619e).
xc_microtheory(a65b127549619e,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549619e,887).
xc_kb_names(a65b127549619e,[]).
xc_mapping_rows(a65b127549619e,[]).
x_comment(x_HostileUnitFn,"(#$HostileUnitFn ORG) denotes the collection of instances of #$ModernMilitaryUnit-Deployable that are hostile to ORG.  More precisely, something, FOE, is an instance of \n(#$HostileUnitFn ORG) just in case there is a #$Organization, MIL, such that \n(#$hasMembers MIL FOE) and there is a #$ConflictEvent, CON, such that \n(opponentsInConflict ORG MIL CON).  Often this function will be used within a COA planning context.  In such contexts (#$HostileUnitFn #$Red-Side) denotes the collection of forces hostile to the #$Red-Side, i.e. all the members of the #$Blue-Side.") :- x_cid(a65b127549619f).
xc_microtheory(a65b127549619f,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549619f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
