x_comment(x_BypassingAnEnemy,"To bypass an enemy force is to maneuver around it so as to avoid a confrontation.  When conducting a bypass, the commander deliberately avoids combat with an enemy force so that all of his combat power is directed toward mission accomplishment. For a more general notion of bypassing something, see #$BypassingSomething.") :- x_cid(a65b12754961b0).
xc_microtheory(a65b12754961b0,x_ModernMilitaryTacticsMt).
