x_comment(x_InfiltratingAnArea,"An infiltration is the covert movement through or into an area occupied by enemy forces to occupy a position of advantage in the enemy's rear while exposing only small elements to enemy defensive fires. ... To successfully infiltrate, the force must avoid detection and engagement. Since this requirement limits the size of the infiltrating force, infiltration is normally used in conjunction with, and in support of, the other choices of maneuver. Infiltration is also a movement technique used within friendly territory to move forces in small groups at extended or irregular intervals. FM100-40, p3-27,28.") :- x_cid(a65b12754961b2).
xc_microtheory(a65b12754961b2,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961b2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
