xc_mapping_rows(a65b12754961b2,[]).
x_comment(x_RetreatingFromAnArea,"A specialization of #$LeavingAPlace.  Each instance of #$RetreatingFromAnArea is an event in which some military force retreats from an area. The retreating force need not have been in previous contact with enemy forces; for this narrower notion, see #$WithdrawingFromCombat.") :- x_cid(a65b12754961b3).
xc_microtheory(a65b12754961b3,x_ModernMilitaryTacticsMt).
