xc_mapping_rows(a65b12754961b3,[]).
x_comment(x_CoordinatedFireLine,"A line beyond which conventional surface fire support means (mortars, field artillery, naval gunfire ships) may fire at any time within the zone of the establishing headquarters without additional coordination. It is usually established by brigade or division but may be established by a maneuver battalion.") :- x_cid(a65b12754961b4).
xc_microtheory(a65b12754961b4,x_ModernMilitaryTacticsMt).
