x_comment('x_MilitarySupplyPoint-ClassII',"The collection of instances of #$MilitarySupplyPoint at which clothing, individual equipment, tents, organizational tool sets and kit, hand tools, maps and adminstrative and housekeeping supplies and equipment are located and issues. FM 101-5-1.") :- x_cid(a65b12754961b5).
