x_comment(x_ControllingAnObjective,"To control the enemy is to maintain physical influence over him by occupying an area or dominating the area through the use of direct fire weapon systems. The tactical task of control differs from that of secure because secure does not allow enemy fires to impact on the area being secured. In control, the enemy can engage targets within the controlled area but cannot move his ground forces through the area at will.") :- x_cid(a65b12754961b6).
xc_microtheory(a65b12754961b6,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961b6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754961b6,937).
