xc_mapping_rows(a65b12754961b6,[]).
x_comment(x_LineOfDeparture,"1. In land warfare, a line designated to coordinate the departure of attack elements. 2. In amphibious warfare, a suitably marked offshore coordinating line to assist assault craft to land on designated beaches at scheduled times. (See also #$LineOfContact (LC)). See FMs 1-111, 7-7, 7-8, 7-10, 7-20, 7-30, 17-15, 17-95, 31-12, and 71-123. 3-15.") :- x_cid(a65b12754961b7).
xc_microtheory(a65b12754961b7,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961b7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
