xc_mapping_rows(a65b12754961b7,[]).
x_comment(x_hostileUnitType,"(#$hostileUnitType ORG UNIT-COLL) holds just in case UNIT-COLL is the collection of\ninstances of #$ModernMilitaryUnit-Deployable that are hostile to ORG.  The is the corresponding predicate to #$HostileUnitFn.") :- x_cid(a65b12754961b8).
xc_microtheory(a65b12754961b8,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961b8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
