xc_mapping_rows(a65b12754961b8,[]).
x_comment(x_ForwardArmingAndRefuelingPoint,"A temporary facility that is organized, equipped, and deployed by an aviation commander, and is normally located in the main battle area closer to the area of operations than the aviation unit's combat service support area. It provides fuel and ammunition necessary for the employment of aviation maneuver units in combat. It permits combat aircraft to rapidly refuel and rearm simultaneously. See FMs 1-111, 7-30, 71-100, 100-15, and 100-103.") :- x_cid(a65b12754961b9).
xc_microtheory(a65b12754961b9,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961b9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
