x_comment('x_SearchAndAttack-MilitaryOperation',"This is the collection of instances of #$MilitaryOperation that are performed by smaller, light maneuver units, and air cavalry or air assault units in large areas. It is used when the enemy disperses in an area of close terrain that is unsuited for heavy forces, when enemy weaknesses cannot be found, or to deny the enemy movement in an area. FM 100-5.") :- x_cid(a65b12754961bb).
xc_microtheory(a65b12754961bb,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961bb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
