x_comment(x_AssemblyAreaOccupied,"1. An area in which a command is assembled preparatory to further action. 2. In a supply installation, the gross area used for collecting and combining components into complete units, kits, or assemblies. See FMs 7-20, 7-30, and 71-123.") :- x_cid(a65b12754961bc).
xc_microtheory(a65b12754961bc,x_ModernMilitaryTacticsMt).
