x_comment(x_PenetratingADefense,"A type of action in which an agent breaks through an adversary's defense, usually with the intent of disrupting the defensive system. Instances of this sort of event include military units penetrating enemy lines as well as sports teams penetrating an opponent's defense.") :- x_cid(a65b12754961be).
xc_microtheory(a65b12754961be,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961be,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
