x_comment(x_DestroyingAnEnemyForce,"To destroy an enemy force is to physically render it combat-ineffective until it is reconstituted. The amount of damage needed to render a unit combat-ineffective depends on the unit's type, discipline, and morale. It normally requires greater than percent personnel or equipment casualties. Destroying armored or dug-in targets with area fire weapons requires a large amount of ammunition and  considerable time, so forces do not normally attempt it unless they have terminally guided munitions.") :- x_cid(a65b12754961c1).
xc_microtheory(a65b12754961c1,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961c1,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754961c1,960).
xc_kb_names(a65b12754961c1,[]).
xc_mapping_rows(a65b12754961c1,[]).
x_comment(x_pointsOfCenterLineTraversal,"(#$pointsOfCenterLineTraversal PATH (ITEM1,...,ITEMN)) means that the centerline of the #$Path-Spatial PATH, considered as a traversal, traverses the geographic reference points ITEM1 through ITEMN in the order listed.") :- x_cid(a65b12754961c2).
xc_microtheory(a65b12754961c2,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961c2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
