xc_mapping_rows(a65b12754961c2,[]).
x_comment(x_TacticalLine,"A collection of line-like #$GeographicalThings.  Each\ninstance of #$TacticalLine is a geographical line with\ntactical significance in the context of some (actual or hypothetical)\nmilitary operations. As a rule, any particular #$TacticalLine should\nbe asserted to be an instance of a specialization of this collection,\nsuch as #$PhaseLine or ForwardLineOfOwnTroops. Note that a\n#$TacticalLine need not be truly one-dimensional, as long as its size\nin all but one dimension is smaller than the granularity of\ngeographical coordinates used in the tactical context. See also\n#$TacticalPoint and #$TacticalArea.") :- x_cid(a65b12754961c3).
xc_microtheory(a65b12754961c3,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961c3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754961c3,962).
xc_kb_names(a65b12754961c3,[]).
xc_mapping_rows(a65b12754961c3,[]).
x_comment(x_TerrainSeverelyRestricted,"Severely restricted terrain defined in FM 34-130 as terrain\nthat severely hinders or slows movement formations unless some effort\nis made to enhance mobility.  For armored and mechanized forces, this\nis typically characterized by steep slopes and large or densely spaced\nobstacles with little or no supporting roads.") :- x_cid(a65b12754961c4).
xc_microtheory(a65b12754961c4,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961c4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
