xc_mapping_rows(a65b12754961c4,[]).
x_comment(x_FriendlyUnitFn,"(#$FriendlyUnitFn ORG) denotes the collection of instances of #$ModernMilitaryUnit-Deployable that are Friendly to ORG.  Often this function will be used within a COA planning context.  In such contexts (#$FriendlyUnitFn #$Red-Side) denotes the collection of forces friendly to the #$Red-Side, i.e. the members of #$Red-Side.  For a similar but opposite function see #$HostileUnitFn.") :- x_cid(a65b12754961c5).
