x_comment(x_coaAddressesMissionEssentialTaskSet,"(#$coaAddressesMissionEssentialTaskSet  COAMT SET) means that the course of action specified by  COAMT addresses the mission essential task as specified by SET.") :- x_cid(a65b12754961c8).
