x_comment(x_IsolatingAnEnemy,"A specialization of ContainingAnEnemy. To isolate an enemy force is to seal it off physically and psychologically from sources of support. As with containment, isolation involves denying an enemy freedom of movement and contact with other enemy forces.") :- x_cid(a65b12754961ca).
