x_comment(x_tenureInUnitPosition,"(#$tenureInUnitPosition POSITION MMO AGENT DURATION) means that, in the context of the assertion, AGENT holds POSITION in MMO, and has held that position for DURATION.  More specifically, if it #$holdsIn\ntime interval TEMP that (#$tenureInUnitPosition POSITION MMO AGENT) and INT is any time interval of #$duration DURATION that is #$temporallyFinishedBy TEMP, then (POSITION MMO AGENT) #$holdsIn\nINT.") :- x_cid(a65b12754961d0).
