x_comment(x_CanalizingAnEnemyForce,"To canalize is to restrict enemy movement to a narrow zone by exploiting terrain coupled with the use of obstacles, fires, or friendly maneuver. Successful canalization results in moving the enemy formation into a predetermined position where it is vulnerable to piecemeal destruction by direct and indirect fires. The same effect occurs when an enemy force is taken under fire and individual enemy soldiers and combat systems seek positions that are masked from the effects of friendly fires. When this occurs, further enemy movements are usually canalized into areas outside of the 'beaten zone' established by the effects of the friendly force's fire, and thus can be fairly easy to predict.") :- x_cid(a65b12754961e7).
xc_microtheory(a65b12754961e7,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961e7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
