x_comment('x_MovementToContact-MilitaryOperation',"A movement to contact is an attack to gain or reestablish contact with the enemy. A properly executed movement to contact develops the combat situation and maintains the commander's freedom of action after contact is gained.  This flexibility is essential in maintaining the initiative. Enemy forces (other than the final objective) within the assigned area will be put at a disadvantage by being disrupted, fixed or defeated. The movement to contact terminates when it reaches its final objective or limit of advance, or must conduct a deliberate attack, a hasty defense, or retrograde. FM100-40, Ch4.") :- x_cid(a65b12754961ec).
xc_microtheory(a65b12754961ec,x_ModernMilitaryTacticsMt).
