x_comment(x_PhaseLine,"A line used for control and coordination of military operations, usually a terrain feature extending across the zone of action. (Army) - It is usually along a recognizable terrain feature extending across the sector or zone of action. Units normally report crossing PLs, but do not halt unless specifically directed. From FM 101-5-1.") :- x_cid(a65b12754961ed).
