x_comment(x_FinalCoordinationLine,"A line close to the enemy position used to coordinate the\nlifting or shifting of supporting fires with the final deployment of\nmaneuver elements. It should be recognizable on the ground. It is not\na fire support coordination measure.") :- x_cid(a65b12754961ee).
