x_comment(x_MilitaryPost,"An instance of #$MilitaryPost is a physical and \nengineered location that is intended to serve the purposes of a military unit.\nSpecializations include #$CommandPost and #$ObservationPost. A #$MilitaryPost need not be a building or obviously constructed area, but may be a position that has been modified for military suitability by other mean, such as digging and levelling.") :- x_cid(a65b12754961ef).
