x_comment(x_CounteringEnemyReconnaissance,"Counterreconnaissance is all measures taken to counter enemy reconnaissance and surveillance efforts throughout the depth of the area of operations (AO). Counterreconnaissance is not a distinct mission, but a component of security operations. It prevents hostile observation of a force, area, or place. Counterreconnaissance is  an element of all security operations and most local security measures. It involves both active and passive elements and includes combat action to destroy or repel enemy reconnaissance units. Stripping away enemy ground reconnaissance while denying the enemy information through other collection systems allows friendly force commanders to operate against an enemy who is operating blindly. The enemy commander's inability to see the battlefield will eventually desynchronize his actions and render his command vulnerable to aggressive action by friendly forces.") :- x_cid(a65b12754961f3).
xc_microtheory(a65b12754961f3,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961f3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754961f3,1066).
xc_kb_names(a65b12754961f3,[]).
xc_mapping_rows(a65b12754961f3,[]).
