x_comment(x_RestrictiveFireLine," A line established between converging friendly forces (one or both may be moving) that prohibits fires or effects from fires across the line without coordination with the affected force. It is established by the next higher common commander of the converging forces.") :- x_cid(a65b12754961f7).
