x_comment(x_SeizingAnObjective,"A type of #$TakingSomething in which an agent (e.g. a military force) obtains control of a region or other tangible objective through the use (or threat) of force. In general, when an objective is seized, this suggests that the seizing agent has taken steps to retain control of the objective. For example, when a military unit seizes an objective, this normally entails that the unit has both obtained control of the objective (#$ControllingAnObjective) and cleared the area of enemy forces (#$ClearingAnEnemy).") :- x_cid(a65b12754961f8).
xc_microtheory(a65b12754961f8,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961f8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b12754961f8,1072).
xc_kb_names(a65b12754961f8,[]).
xc_mapping_rows(a65b12754961f8,[]).
x_comment('x_criterialForTerrainTacticalRole-Positive',"(#$criterialForTerrainTacticalRole-Positive TERRAIN-TYPE\nSET-TERM) means that membership in SET-TERM constitutes a positive criteria\nfor effectively serving the tactical role associated with\nTERRAIN-TYPE. SET-TERM is a term constructed with #$TheSetOf plus a\nsentence. So: if an instance X of #$GeographicalThing satisfies that\nsentence, hence belongs to SET-TERM, that counts in favor of using X\ntactically as a TERRAIN-TYPE in the given planning context.  Contrast with\n#$criterialForTerrainTacticalRole-Negative.") :- x_cid(a65b12754961f9).
xc_microtheory(a65b12754961f9,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961f9,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
