xc_mapping_rows(a65b12754961f9,[]).
x_comment(x_AirApproach,"Characteristic attribute of an approach corridor employed by air traffic.") :- x_cid(a65b12754961fa).
xc_microtheory(a65b12754961fa,x_ModernMilitaryTacticsMt).
