x_comment(x_advanceGuardSupport,"(#$advanceGuardSupport SUPPORT UNIT) says that UNIT plays the role of 'support' advance guard in the #$SupportingAUnit event SUPPORT.  Specifically, there is a larger unit of which UNIT is a part, the larger unit has been assigned a task, and UNIT has been sent out ahead of the larger unit to ensure its ability to advance and carry out its task.  During SUPPORT, UNIT gives direct support to the unit that acts as #$advanceGuardReserve.") :- x_cid(a65b12754961fb).
xc_microtheory(a65b12754961fb,x_ModernMilitaryTacticsMt).
xc_source_file(a65b12754961fb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
