x_comment('x_RiverCrossing-Deliberate',"There are three basic types of river crossings: hasty, deliberate, and retrograde. A hasty river crossing is a task conducted as part of a larger operation, typically an attack, with no intentional pause at the water line. When a hasty river crossing is not feasible such as when the enemy or terrain situations prevent it, a hasty crossing attempt fails, or friendly offensive operations resume at a river line after a pause, the force conducts a deliberate river crossing operation. A retrograde river crossing is a movement to the rear across a water obstacle while in contact with the enemy.  A river crossing is both a tactical task and an enabling operation. Field Manual 90-13, River Crossing Operations, gives detailed information concerning the conduct of a river crossing.") :- x_cid(a65b1275496204).
xc_microtheory(a65b1275496204,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496204,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496204,1095).
xc_kb_names(a65b1275496204,[]).
xc_mapping_rows(a65b1275496204,[]).
x_comment(x_taskTypeCommensurateWithOpType,"(#$taskTypeCommensurateWithOpType TASK_TYPE OP_TYPE) means\nthat in normal circumstances, we would expect to find a #$MilitaryAction\nof type TASK_TYPE associated with a #$MilitaryOperation of type\nOP_TYPE, probably via the #$taskOfOperation relation.  This may be\nsaid to hold to the extent that, if a task and operation are\nassociated via #$taskOfOperation in a COA and it is not the case that\nthe asserted task type is #$taskTypeCommensurateWithOpType with the\nasserted operation type, it may be indicative of a flaw in the COA.") :- x_cid(a65b1275496205).
xc_microtheory(a65b1275496205,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496205,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496205,1096).
