x_comment(x_PassageOfLines,"In this type of action, a military unit moves through another (friendly) unit's position with the intent of moving into or out of enemy contact. It involves the transfer of responsibility for fighting an enemy force from one unit to another in close operations.") :- x_cid(a65b1275496209).
xc_microtheory(a65b1275496209,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496209,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
