x_comment(x_MilitaryThreat,"A collection of attributes: a unit with an attribute value\nfrom this collection is a hostile force which presents a friendly\nforce with a threat of some degree in the context of a Course of\nAction representation.") :- x_cid(a65b127549620a).
xc_microtheory(a65b127549620a,x_ModernMilitaryTacticsMt).
