xc_mapping_rows(a65b127549620a,[]).
x_comment(x_CapabilityBasedSurpriseAttack,"The collection of #$SurpriseAttacks whose element of\nsurprise depend on the the attacker's use of capabilities\nthe enemy did not expect.") :- x_cid(a65b127549620b).
xc_microtheory(a65b127549620b,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549620b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
