xc_mapping_rows(a65b127549620b,[]).
x_comment('x_Encirclement-MilitaryManeuver',"Encirclements are intended to enclose and capture or defeat large enemy forces. Typically, encirclements either result from penetrations and envelopments or are an extension of exploitation and pursuit operations. .. They may be planned sequels or result from the exploitation of an unforeseen opportunity. They usually result from the linkup of two forces conducting a double envelopment. However, they can occur in situations where a major obstacle such as a shoreline can be used as the second encircling wing by the attacking commander. Although terrain objectives may be designated in an encirclement, isolation and defeat of enemy forces are the primary goals. FM100-40, p9-7.") :- x_cid(a65b127549620c).
xc_microtheory(a65b127549620c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549620c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549620c,1124).
xc_kb_names(a65b127549620c,[]).
xc_mapping_rows(a65b127549620c,[]).
x_comment(x_militaryOrgDoctrineIncludesEventType,"A predicate relating a #$MilitaryOrganization to the\ndoctrinal event (e.g., task and operation) classifications to which it\nsubscribes.  For example, (#$militaryOrgDoctrineIncludesEventType\n#$UnitedStatesArmy #$ClearingAnEnemy), since #$ClearingAnEnemy\ndenotes a type of task defined by U.S. Army doctrine.") :- x_cid(a65b127549620d).
xc_microtheory(a65b127549620d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549620d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549620d,1125).
xc_kb_names(a65b127549620d,[]).
xc_mapping_rows(a65b127549620d,[]).
x_comment(x_MilitaryDecisionMakingActionType,"This is a collection of specializations of #$PurposefulAction.  Instances of this collection represent the different types of action which make up the military decision-making process. Specializations of this collection include #$METT-TC-EvaluationType and COASpecificationDimension.") :- x_cid(a65b127549620e).
xc_microtheory(a65b127549620e,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549620e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549620e,1130).
xc_kb_names(a65b127549620e,[]).
xc_mapping_rows(a65b127549620e,[]).
x_comment(x_BlockingAnEnemy,"To block is to deny the enemy access to a given area or prevent his advance in a given direction or along an avenue of approach. A blocking task normally requires the friendly force to block the enemy force for a certain time period or until a specific event has occurred. A blocking unit may have to hold terrain and accept decisive engagement. A block differs from a fix because a blocked enemy force can move in any direction other than the obstructed one while a fixed enemy force cannot move in any direction.") :- x_cid(a65b127549620f).
xc_microtheory(a65b127549620f,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549620f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549620f,1131).
xc_kb_names(a65b127549620f,[]).
xc_mapping_rows(a65b127549620f,[]).
x_comment('x_AreaSecurity-MilitaryOperation',"Area security operations are conducted to protect friendly forces, installations, and actions in a specific area. ... They focus on the force, installation, or area to be protected. ... During conventional operations, area security operations are normally an economy of force measure designed to ensure the continued sustainment of the main effort.") :- x_cid(a65b1275496210).
xc_microtheory(a65b1275496210,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496210,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496210,1132).
