x_comment(x_CoordinatingPoint,"A designated point at which adjacent units/formations must make contact for purposes of control and coordination. (Army) A control measure that indicates a specific location for the coordination of fires and maneuver between adjacent units. They usually are indicated whenever a boundary crosses the forward edge of the battle area (FEBA) and may be indicated when a boundary corsses phase lines (PLs) used to control security forces. (In NATO, physical contact between adjacent units is required.) (See also #$ContactPoint.)") :- x_cid(a65b1275496218).
