xc_mapping_rows(a65b127549621b,[]).
x_comment(x_FireSupportCoordinationLine,"A line established by the appropriate land or amphibious force commander to ensure coordination of fire not under the commander s control but which may affect current tactical operations. The FSCL is used to coordinate fires of air, ground, or sea weapons systems using any type of ammunition against surface targets. The FSCL should follow well-defined terrain features. The establishment of the FSCL must be coordinated with the appropriate tactical air commander and other supporting elements. Supporting elements may attack targets forward of the FSCL without prior coordination with the land or amphibious force commander provided the attack will not produce adverse surface effects on or to the rear of the line. Attacks against surface targets behind this line must be coordinated with the appropriate land or amphibious force commander. (Army) - A permissive fire control measure established and adjusted by the ground commander in consultation with superior, subordinate, supporting, and other affected commanders. It is not a boundary the responsibility of the establishing commander out to the limits of the land component forward boundary. It applies to all fires of air, land, and sea weapon systems using any type of ammunition against surface targets. Forces attacking targets beyond the FSCL must inform all affected commanders to allow necessary coordination to avoid fratricide. (See also #$CoordinatedFireLine (CFL).) See FMs 6-20 series, 7-20, 7-30, 17-95, 71-100, 71-123, 100-5, 100-15, and JP 3-0.") :- x_cid(a65b127549621c).
xc_microtheory(a65b127549621c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549621c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549621c,1158).
xc_kb_names(a65b127549621c,[]).
xc_mapping_rows(a65b127549621c,[]).
x_comment(x_DefaultTacticalTargetType,"A collection of collections.  Each instance of\n\n          #$DefaultTacticalTargetType is a collection \n\n          (a specification of #$SpatialThing-Localized)\n\n          of objects that will, by default, be\n\n          of tactical interest on a battlefield and therefore\n\n          candidates for reconnaissance or fire either in\n\n          battle or in preparation\n\n          for a battle.  Examples include military units,\n\n          instances of #$MilitaryPost and #$RoadwayJunction as\n\n          well as certain terrain features\n\n          such as some wooded areas and instances of #$Bridge,\n\n          #$Hill.") :- x_cid(a65b127549621d).
xc_microtheory(a65b127549621d,x_ModernMilitaryTacticsMt).
