x_comment('x_Linkup-MilitaryTask',"A linkup is a meeting of friendly ground forces and occurs in a variety of circumstances. It happens when an advancing force reaches an objective area previously seized by an airborne or air assault when an encircled element breaks out to rejoin friendly forces or a force comes to the relief of an encircled force maneuver forces meet. Both forces may be moving toward each other or one may be stationary. Whenever possible, joining forces exchange as much information as possible prior to the start of an operation.") :- x_cid(a65b127549622b).
xc_microtheory(a65b127549622b,x_ModernMilitaryTacticsMt).
