x_comment(x_TerrainLowGround,"A military term and an instance of #$TerrainTypeBySurfaceLevel. The central feature point of low ground terrain is typically (though not necessarily) lower in altitude than the surrounding terrain. Instances of #$TerrainLowGround are #$Places that require one to traverse a negative slope in order to reach the central feature point. From a tactical standpoint, it is typically assumed that instances of #$TerrainLowGround impede observation.") :- x_cid(a65b127549622d).
xc_microtheory(a65b127549622d,x_ModernMilitaryTacticsMt).
