x_comment('x_RiverCrossing-Hasty',"There are three basic types of river crossings: hasty, deliberate, and retrograde. A hasty river crossing is a task conducted as part of a larger operation, typically an attack, with no intentional pause at the water line. When a hasty river crossing is not feasible such as when the enemy or terrain situations prevent it, a hasty crossing attempt fails, or friendly offensive operations resume at a river line after a pause, the force conducts a deliberate river crossing operation. A retrograde river crossing is a movement to the rear across a water obstacle while in contact with the enemy.  A river crossing is both a tactical task and an enabling operation. Field Manual 90-13, River Crossing Operations, gives detailed information concerning the conduct of a river crossing.") :- x_cid(a65b1275496233).
xc_microtheory(a65b1275496233,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496233,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
