x_comment(x_structureOfUnitUnspecified,"In the context of a particular COA, (#$structureOfUnitUnspecified UNIT) means that the number and type of the subunits of UNIT are not specified.  UNIT is represented in the sketch of the COA as a non-TOGG (Task Organized Combination Graphics) unit and its #$combatForceValueOfUnit can be derived directly from its #$MilitaryUnitSpecialtyType  and #$MilitaryEchelon level.") :- x_cid(a65b1275496234).
xc_microtheory(a65b1275496234,x_ModernMilitaryTacticsMt).
