x_comment('x_TurningMovement-MilitaryManeuver',"In a turning movement, an attacking force seeks to pass around and avoid the enemy's main force, then secure an objective deep in the hostile rear area that causes the enemy to move out of its current positions or divert major forces to meet the threat. A commander uses this choice of maneuver when the opportunity exists to seize vital areas in the hostile rear before the main enemy force can withdraw or receive support or reinforcements. A supporting effort may be required to fix the enemy, such as an envelopment. However, a turning movement is not always accompanied by a supporting effort. A turning movement differs from an envelopment because the force conducting a turning movement is normally out of supporting range of the main body but is within supporting distance. This choice of maneuver frequently transitions from the attack into an exploitation or pursuit. Although the turning force is frequently the main force, it may not always be. FM100-40.") :- x_cid(a65b127549623c).
xc_microtheory(a65b127549623c,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549623c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549623c,1248).
xc_kb_names(a65b127549623c,[]).
xc_mapping_rows(a65b127549623c,[]).
x_comment(x_taskBeatenZone,"(#$taskBeatenZone TASK AREA) means that AREA is circumscribed by the cone of fire generated by the offensive task TASK.  This predicate is generally used for specifying the beaten zone of an #$AttackingByFire-Indirect.") :- x_cid(a65b127549623d).
xc_microtheory(a65b127549623d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549623d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b127549623d,1249).
xc_kb_names(a65b127549623d,[]).
xc_mapping_rows(a65b127549623d,[]).
x_comment(x_HighPayoffTacticalTargetType,"A collection of collections, each instance COL of\n#$HighPayoffTacticalTargetType is a collection of objects\nthat by default will be a target by opposing\nforces during or in preparation for a battle. \nIn other words, we assume\nthat a threat to a particular military force\nwill target with artillery, reconnaissance, or other\nof their unit-types, when feasible, instances of COL\nunless we have information to the contrary.") :- x_cid(a65b127549623e).
xc_microtheory(a65b127549623e,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549623e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
