x_comment(x_unitAssignedMainOpEffort,"(unitAssignedMainOpEffort MISSION UNIT) means that UNIT\nundertakes the main effort in carrying through MISSION.") :- x_cid(a65b127549623f).
xc_microtheory(a65b127549623f,x_ModernMilitaryTacticsMt).
