x_comment(x_temporalStage,"(#$temporalStage WHOLE MT SUB) means that SUB is the           temporal subastraction of WHOLE that is picked out by           the #$mtTime of the #$Microtheory, MT. This presupposes           that WHOLE #$temporallySubsumes the specified #$mtTime           of MT. In general, assertions of the form (#$temporalStage           WHOLE MT SUB) will be made in contexts to which MT           itself has access.") :- x_cid(a65b1275496241).
xc_microtheory(a65b1275496241,x_ModernMilitaryTacticsMt).
