x_comment('x_Demonstration-MilitaryOperation',"A demonstration is a show of force in a location where the commander does not seek to conduct decisive operations.  Its aim is to deceive the enemy. It is similar to a feint, except that contact with the enemy is not sought. FM100-40, p3-8.") :- x_cid(a65b1275496246).
xc_microtheory(a65b1275496246,x_ModernMilitaryTacticsMt).
