x_comment('x_ForwardDefense-MilitaryManeuver',"The collection of those defensive military maneuvers which are used to prevent significant enemy penetration into the defensive sector. The majority of the unit's combat power deploys into forward defensive positions near the forward edge of the battle area.") :- x_cid(a65b1275496248).
