x_comment('x_Raid-MilitaryOperation',"A raid is usually a limited objective, small-scale operation involving swift penetration of enemy territory. It is designed to secure information, confuse the enemy, or destroy his installations. FM100-40, p3-7.") :- x_cid(a65b127549624c).
xc_microtheory(a65b127549624c,x_ModernMilitaryTacticsMt).
