x_comment(x_NoFireLine,"A line short of which artillery or ships do not fire except\non request or approval of the supported commander, but beyond which\nthey may fire at any time without danger to friendly troops.") :- x_cid(a65b127549624f).
xc_microtheory(a65b127549624f,x_ModernMilitaryTacticsMt).
