xc_kb_names(a65b1275496250,[]).
xc_mapping_rows(a65b1275496250,[]).
x_comment(x_intentOfCommanderForAction,"(#$intentOfCommanderForAction COMMANDER ACTION PROP) means\n\nthat the proposition PROP is part of the intent of the individual\n\nserving as the #$commanderForCOA in the COA development context for the\n\n#$MilitaryEvent ACTION. In the associated\n\n#$COACommandIntentMicrotheory, ACTION will have PROP as its\n\n#$taskHasPurpose in the relevant #$COACommandIntentMicrotheory") :- x_cid(a65b1275496251).
xc_microtheory(a65b1275496251,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496251,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
xc_source_line(a65b1275496251,1297).
xc_kb_names(a65b1275496251,[]).
xc_mapping_rows(a65b1275496251,[]).
x_comment('x_posting-Military-Generic',"(#$posting-Military-Generic UNIT REG) means that UNIT is posted to\n\nREG in the time frame of the assertion, and moreover has the\n\nentailment that if (#$geographicalSubRegions SUPER-REG REG), then\n\n(#$posting-Military-Generic UNIT SUPER-REG), provided SUPER-REG is itself known\n\nto be #$geographicalSubRegions of an instance of #$IndependentCountry.\n\nThus, for example, a unit whose #$posting-Military-Generic is Camp Mabry also\n\nhas the #$CityOfAustinTX as a #$posting-Military-Generic, as well as Travis\n\nCounty, #$Texas-State, and the #$UnitedStatesOfAmerica.") :- x_cid(a65b1275496252).
xc_microtheory(a65b1275496252,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496252,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
