xc_kb_names(a65b1275496252,[]).
xc_mapping_rows(a65b1275496252,[]).
x_comment(x_DefeatingAnOpponent,"Instances of this collection are events in which an agent effectively nullifies an adversary's ability to persue opposing goals in a conflict. In general, this means that the adversary has either become unwilling or unable to further pursue his intended course of action. See also #$ConflictEvent.") :- x_cid(a65b1275496253).
xc_microtheory(a65b1275496253,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496253,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
