xc_mapping_rows(a65b1275496253,[]).
x_comment('x_MilitarySupplyPoint-ClassV',"The collection of instances of #$MilitarySupplyPoint at which ammunition of all types including chemical, bombs, explosives, mines, fuzes, detonators, pyrotechnics, missiles, rockets, propellants, and other associated items are located and issues. FM 101-5-1.") :- x_cid(a65b1275496254).
xc_microtheory(a65b1275496254,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496254,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
