xc_mapping_rows(a65b1275496254,[]).
x_comment(x_WithdrawingUnderPressure,"This is a planned, voluntary disengagement from the enemy which is performed under enemy pressure.") :- x_cid(a65b1275496255).
xc_microtheory(a65b1275496255,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496255,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
