xc_mapping_rows(a65b1275496255,[]).
x_comment(x_BattlePositionOccupied,"1. A defensive location oriented on the most likely enemy #$AvenueOfApproach from which a unit may defend. Such units can be as large as battalion task forces and as small as platoons.  A unit assigned a BP is located within the general outline of the BP. A battle position graphic #$ControlMeasure may be used independently or in combination with sectors. Security, combat support, and combat service support forces may operate outside a BP. 2. For attack helicopters, an area designated in which they can maneuver and fire into a designated #$EngagementArea or engage targets of opportunity. (See also defend.) See FMs 1-112, 7-8, 7-20, 7-30, and 71-123.") :- x_cid(a65b1275496256).
xc_microtheory(a65b1275496256,x_ModernMilitaryTacticsMt).
xc_source_file(a65b1275496256,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
