x_comment(x_taskInsAreaOfOperations,"(#$taskInsAreaOfOperations TASK AO) means that AO is designated the #$AreaOfOperations of the unit assigned to perform TASK and, by extension, that unit's #$sectorOfResponsibility.") :- x_cid(a65b1275496257).
