x_comment('x_MilitaryTask-Defensive',"The collection comprised of all defensive forms of Task. This collection is *not* a specialization of #$MilitaryDefensiveOperation since #$MilitaryDefensiveOperation is a specialization of #$MilitaryOperation: instances are carried out by several units acting in concert to implement primary and support tasks.  An instance of #$MilitaryDefensiveOperation will be comprised of one or more instances of #$MilitaryTask-Defensive figuring as #$subEvents.") :- x_cid(a65b127549625c).
