x_comment(x_SupportingAttack,"An offensive operation carried out in conjunction with a main attack and designed to achieve one or more of the following: a. deceive the enemy; b. destroy or pin down enemy forces which could interfere with the main attack; c. control ground whose occupation by the enemy will hinder the main attack; or d. force the enemy to commit reserves prematurely or in an indecisive area.") :- x_cid(a65b127549627b).
xc_microtheory(a65b127549627b,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549627b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
