x_comment(x_unitAssignedSuppOpEffort,"(unitAssignedSuppOpEffort MISSION UNIT) means that UNIT\nundertakes one of the supporting efforts in carrying through MISSION.") :- x_cid(a65b127549627c).
xc_microtheory(a65b127549627c,x_ModernMilitaryTacticsMt).
