x_comment(x_specializedEquipmentOfUnitType,"(#$specializedEquipmentOfUnitType UNITTYPE THINGTYPE) means that, within a military context, instances of THINGTYPE are supplied specially for use by units of type UNITTYPE, and under  'ordinary' or 'normal' circumstances instances of THINGTYPE will not be found with units that are not an instance of UNITTYPE.") :- x_cid(a65b127549627d).
xc_microtheory(a65b127549627d,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549627d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
