x_comment('x_AvenueOfApproach-Air',"A specialization of #$AvenueOfApproach for air forces.  An\n#$AvenueOfApproach-Air is an aerial route that leads a force to its\nobjective, or to key terrain on its path. Note that in contrast to an\n#$AvenueOfApproach-Ground, an #$AvenueOfApproach-Air must be specified\nby altitude as well as lat-long or other earth surface coordinates.") :- x_cid(a65b127549627e).
xc_microtheory(a65b127549627e,x_ModernMilitaryTacticsMt).
