x_comment(x_MilitaryTaskObstacleFn,"(#$MilitaryTaskObstacleFn TASKTYPE) returns the collection of all instances of #$ObstacleSystem-Military specifically designed to interfere with or prevent the performance of tasks of type TASKTYPE.") :- x_cid(a65b127549627f).
xc_microtheory(a65b127549627f,x_ModernMilitaryTacticsMt).
