x_comment(x_standardEquipmentOfUnitType,"(#$standardEquipmentOfUnitType ?UNITTYPE ?THINGTYPE) means that under 'ordinary' or 'normal' circumstances we should expect to find any instances of?UNITTYPE equipped with one or more instances of ?THINGTYPE.") :- x_cid(a65b1275496280).
