x_comment(x_EncirclingAnEnemy,"This task is assigned to a unit which is an encircling force in an encirclement operation (see FM100-40, pp 9-7 - 9-16). The unit may be designated as the main effort or a supporting effort (if a major obstacle, such as a shoreline, cannot serve as a second encircling wing). Although terrain objectives may be designated in an encirclement, isolation and defeat of enemy forces are the primary goals.") :- x_cid(a65b1275496282).
xc_microtheory(a65b1275496282,x_ModernMilitaryTacticsMt).
