x_comment(x_TerrainFlatGround,"An instance of #$TerrainTypeBySurfaceLevel. Flat ground terrain is the terrain that is neither #$TerrainHighGround nor #$TerrainLowGround. When traversing #$TerrainFlatGround, one will not encounter any significant positive or negative slope.") :- x_cid(a65b1275496283).
xc_microtheory(a65b1275496283,x_ModernMilitaryTacticsMt).
