x_comment(x_ClearingAnEnemy,"To clear an enemy from an area means to remove all enemy forces and eliminate organized resistance in the area. This may be accomplished by destroying, capturing, or forcing the withdrawal of the enemy from the area.") :- x_cid(a65b1275496286).
xc_microtheory(a65b1275496286,x_ModernMilitaryTacticsMt).
