x_comment('x_RearwardPassageOfLines-MilitaryOperation',"A rearward passage of lines occurs when a unit passes through another unit while moving away from the enemy. FM100-40, p18- 2. A rearward passage of lines is similar in concept to a forward passage of lines. It continues the defense or retrograde operation. It maintains enemy contact while allowing for the recovery of the security force or the replacement of a unit that is combat-ineffective.") :- x_cid(a65b127549628a).
xc_microtheory(a65b127549628a,x_ModernMilitaryTacticsMt).
xc_source_file(a65b127549628a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/ModernMilitaryTacticsMt.krf').
