x_comment(x_OffensivelyAdvantageousTerrain,"The collection of geographical regions that are useful for offensive actions. Note that it is possible for a geographical region to be instances of both #$OffensivelyAdvantageousTerrain and #$DefensivelyAdvantageousTerrain. For example, one such case might be a region that is both a #$CoverProvidingTerrain and a #$ObservationFacilitatingTerrain.") :- x_cid(a65b127549628b).
